-- Hub-only tables. Isolated hub_ prefix avoids changing existing CrowRules data.
create extension if not exists pgcrypto;
create table if not exists public.hub_listings(id uuid primary key default gen_random_uuid(),kind text not null check(kind in('business','resource','event','volunteer','job','arts','family','sports','neighborhood','group','lost-found','alert','community')),title text not null check(char_length(title) between 3 and 160),summary text not null check(char_length(summary) between 10 and 1200),category text not null default 'General' check(char_length(category)<=80),neighborhood text check(neighborhood is null or char_length(neighborhood)<=100),address_or_area text check(address_or_area is null or char_length(address_or_area)<=240),start_at timestamptz,end_at timestamptz,cost text check(cost is null or char_length(cost)<=100),website text check(website is null or char_length(website)<=500),contact text check(contact is null or char_length(contact)<=240),submitter_name text check(submitter_name is null or char_length(submitter_name)<=120),submitter_email text check(submitter_email is null or char_length(submitter_email)<=254),source_url text check(source_url is null or char_length(source_url)<=500),status text not null default 'pending' check(status in('pending','approved','rejected','archived')),verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists hub_listings_public_idx on public.hub_listings(kind,status,created_at desc);create index if not exists hub_listings_events_idx on public.hub_listings(start_at) where kind='event' and status='approved';
create table if not exists public.hub_chat_messages(id uuid primary key default gen_random_uuid(),room text not null check(room in('general','neighborhoods','events','business','resources','arts-sports')),nickname text not null check(char_length(nickname) between 2 and 32),body text not null check(char_length(body) between 1 and 700),created_at timestamptz not null default now());create index if not exists hub_chat_room_created_idx on public.hub_chat_messages(room,created_at desc);
create table if not exists public.hub_visitor_presence(session_id uuid primary key,page_path text not null default '/' check(char_length(page_path)<=300),last_seen_at timestamptz not null default now());create index if not exists hub_presence_last_seen_idx on public.hub_visitor_presence(last_seen_at desc);
create table if not exists public.hub_reports(id uuid primary key default gen_random_uuid(),target_type text not null check(target_type in('listing','chat','site')),target_id uuid,reason text not null check(char_length(reason) between 5 and 500),details text check(details is null or char_length(details)<=1000),created_at timestamptz not null default now(),status text not null default 'open' check(status in('open','reviewing','resolved','dismissed')));
create table if not exists public.hub_admins(user_id uuid primary key references auth.users(id) on delete cascade,role text not null default 'moderator' check(role in('admin','moderator')),created_at timestamptz not null default now());
alter table public.hub_listings enable row level security;alter table public.hub_chat_messages enable row level security;alter table public.hub_visitor_presence enable row level security;alter table public.hub_reports enable row level security;alter table public.hub_admins enable row level security;
drop policy if exists "hub public can read approved listings" on public.hub_listings;create policy "hub public can read approved listings" on public.hub_listings for select to anon,authenticated using(status='approved');
drop policy if exists "hub visitors can submit listings for review" on public.hub_listings;create policy "hub visitors can submit listings for review" on public.hub_listings for insert to anon,authenticated with check(status='pending');
drop policy if exists "hub moderators can read all listings" on public.hub_listings;create policy "hub moderators can read all listings" on public.hub_listings for select to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid())));
drop policy if exists "hub moderators can update listings" on public.hub_listings;create policy "hub moderators can update listings" on public.hub_listings for update to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid())));
drop policy if exists "hub public can read recent chat" on public.hub_chat_messages;create policy "hub public can read recent chat" on public.hub_chat_messages for select to anon,authenticated using(created_at>now()-interval '7 days');
drop policy if exists "hub visitors can post chat" on public.hub_chat_messages;create policy "hub visitors can post chat" on public.hub_chat_messages for insert to anon,authenticated with check(char_length(nickname) between 2 and 32 and char_length(body) between 1 and 700);
drop policy if exists "hub public can view live presence" on public.hub_visitor_presence;drop policy if exists "hub visitors can add presence" on public.hub_visitor_presence;drop policy if exists "hub visitors can update presence" on public.hub_visitor_presence;revoke select,insert,update on public.hub_visitor_presence from anon,authenticated;
create or replace function public.hub_touch_presence(p_session_id uuid,p_page_path text) returns void language plpgsql security definer set search_path='' as $$ begin if p_session_id is null then raise exception 'Session is required';end if;insert into public.hub_visitor_presence(session_id,page_path,last_seen_at) values(p_session_id,left(coalesce(p_page_path,'/'),300),now()) on conflict(session_id) do update set page_path=excluded.page_path,last_seen_at=now();delete from public.hub_visitor_presence where last_seen_at<now()-interval '10 minutes';end;$$;
create or replace function public.hub_live_visitor_count() returns integer language sql stable security definer set search_path='' as $$ select count(*)::integer from public.hub_visitor_presence where last_seen_at>now()-interval '3 minutes';$$;
revoke all on function public.hub_touch_presence(uuid,text) from public;revoke all on function public.hub_live_visitor_count() from public;grant execute on function public.hub_touch_presence(uuid,text) to anon,authenticated;grant execute on function public.hub_live_visitor_count() to anon,authenticated;
drop policy if exists "hub visitors can submit reports" on public.hub_reports;create policy "hub visitors can submit reports" on public.hub_reports for insert to anon,authenticated with check(status='open');
drop policy if exists "hub moderators can view reports" on public.hub_reports;create policy "hub moderators can view reports" on public.hub_reports for select to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid())));
drop policy if exists "hub moderators can update reports" on public.hub_reports;create policy "hub moderators can update reports" on public.hub_reports for update to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid())));
drop policy if exists "hub users can read own admin row" on public.hub_admins;create policy "hub users can read own admin row" on public.hub_admins for select to authenticated using(user_id=(select auth.uid()));
grant select,insert on public.hub_listings to anon,authenticated;grant update on public.hub_listings to authenticated;grant select,insert on public.hub_chat_messages to anon,authenticated;grant insert on public.hub_reports to anon,authenticated;grant select,update on public.hub_reports to authenticated;grant select on public.hub_admins to authenticated;
do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='hub_chat_messages') then alter publication supabase_realtime add table public.hub_chat_messages;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='hub_listings') then alter publication supabase_realtime add table public.hub_listings;end if;end $$;
